package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.AuditUser;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestHeader;

/** Adds the comment to the claim, by the signed-in name, dated the sheet's today. A claim of any status can be
 *  commented. */
public class ApplyComment {
    public void apply(@Val CommentRequest comment, @Val Claim claim, @Val Sheet sheet,
            @RequestHeader(name = "X-User", required = false) String user, ClaimCommentRepository comments) {
        comments.saveAndFlush(new ClaimComment(claim, AuditUser.decode(user), sheet.getToday(), comment.text()));
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Reads the comment from the body, its text trimmed; refuses an empty one. */
public class ValidateComment {
    public void validate(@RequestBody CommentRequest request, Out<CommentRequest> comment) throws InvalidClaimException {
        String text = request == null || request.text() == null ? "" : request.text().trim();
        if (text.isEmpty()) {
            throw new InvalidClaimException("A comment cannot be empty.");
        }
        comment.set(new CommentRequest(text));
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.AuditUser;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestHeader;

/** Records the comment, once it is saved: the claim's line, then its text. */
public class AuditCommentAdded {
    public void audit(@Val CommentRequest comment, @Val Claim claim, PersonRepository people,
            @RequestHeader(name = "X-User", required = false) String user, Audit audit) {
        String person = people.findById(claim.getPersonId()).map(Person::getName).orElse("");
        audit.record(ClaimAudit.line("COMMENT_ADDED", claim, person, AuditUser.decode(user)) + " text=" + comment.text());
    }
}
package net.officefloor.hq.app.claim;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.time.LocalDate;

/** One comment on a claim: its text, who wrote it and the sheet's today when it was written. */
@Entity
@Table(name = "claim_comment")
public class ClaimComment {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "claim_id", nullable = false)
    private Long claimId;

    @Column(name = "by_user", nullable = false)
    private String byUser;

    @Column(name = "on_date", nullable = false)
    private LocalDate onDate;

    @Column(nullable = false)
    private String text;

    protected ClaimComment() {
    }

    public ClaimComment(Claim claim, String byUser, LocalDate onDate, String text) {
        this.sheetId = claim.getSheetId();
        this.claimId = claim.getId();
        this.byUser = byUser;
        this.onDate = onDate;
        this.text = text;
    }

    /** A copy of the comment for the claim a transfer made of this comment's claim on another sheet. Not saved. */
    public ClaimComment copyFor(Claim moved) {
        return new ClaimComment(moved, byUser, onDate, text);
    }

    public Long getClaimId() {
        return claimId;
    }

    public LocalDate getOnDate() {
        return onDate;
    }

    public String getText() {
        return text;
    }

    /** The comment as the screen shows it: <user> on <date>: <text>. */
    public String line() {
        return byUser + " on " + onDate + ": " + text;
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import org.springframework.data.jpa.repository.JpaRepository;

public interface ClaimCommentRepository extends JpaRepository<ClaimComment, Long> {

    /** The sheet's comments, oldest first. */
    List<ClaimComment> findBySheetIdOrderByIdAsc(String sheetId);

    /** The claim's comments, oldest first. */
    List<ClaimComment> findByClaimIdOrderByIdAsc(Long claimId);

    /** The claim's comments as the screen shows them, oldest first. */
    default List<String> linesOf(Claim claim) {
        return findByClaimIdOrderByIdAsc(claim.getId()).stream().map(ClaimComment::line).toList();
    }

    /** The comments of each claim on the sheet as the screen shows them, oldest first, by claim id; as of a date
     *  (null: now), only those written while the sheet's today was on or before it. */
    default Map<Long, List<String>> linesOnSheet(String sheetId, LocalDate date) {
        return findBySheetIdOrderByIdAsc(sheetId).stream().filter(c -> date == null || !c.getOnDate().isAfter(date))
                .collect(Collectors.groupingBy(ClaimComment::getClaimId,
                        Collectors.mapping(ClaimComment::line, Collectors.toList())));
    }
}
